/* 把文本拆成 text / code / iui 三段 */
function parseParts(raw){
  var parts=[], i=0, re=/```([a-zA-Z0-9_+-]*)\r?\n?([\s\S]*?)```/g, m;
  while((m=re.exec(raw))){
    if(m.index>i) parts.push({t:'text',v:raw.slice(i,m.index)});
    var lang=(m[1]||'').toLowerCase();
    if(lang==='iui'){try{parts.push({t:'iui',v:JSON.parse(m[2])})}catch(e){parts.push({t:'code',lang:lang,v:m[2]})}}
    else parts.push({t:'code',lang:lang,v:m[2]});
    i=re.lastIndex;
  }
  if(i<raw.length) parts.push({t:'text',v:raw.slice(i)});
  return parts;
}

